const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-interference\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '2d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const D = __narration.durationSec;
  let cursor = 0;
  const play = (actions, duration) => { s.play(actions, { duration, ease: 'linear' }); cursor += duration; };
  s.play(s.camera.to2D({ height: 8.8, target: [0,0,0] }), { duration: 0 });
  // Equal-amplitude idealization: u/2 = cos(k(r1-r2)/2) cos(k(r1+r2)/2 - omega*t).
  const a = 1.5, wavelength = 1.6;
  const k = 2*Math.PI/wavelength, period = D*0.3, omega = 2*Math.PI/period;
  const xmax = 4.8, ymax = 2.6;
  const nx = 80, ny = 44, phases = 16, levels = 4;
  const buckets = Array.from({ length: phases*levels }, () => ({ vertices: [], triangles: [] }));
  const dx = 2*xmax/nx, dy = 2*ymax/ny;
  for (let j=0; j<ny; j++) for (let i=0; i<nx; i++) {
    const x = -xmax+(i+0.5)*dx, y = -ymax+(j+0.5)*dy;
    const r1 = Math.hypot(x+a,y), r2 = Math.hypot(x-a,y);
    const envelope = Math.cos(k*(r1-r2)/2);
    if (Math.abs(envelope)<0.035) continue;
    const phase = k*(r1+r2)/2+(envelope<0 ? Math.PI : 0);
    const p = ((Math.round(phase*phases/(2*Math.PI))%phases)+phases)%phases;
    const level = Math.min(levels-1,Math.floor(Math.abs(envelope)*levels));
    const b = buckets[p*levels+level], n = b.vertices.length;
    b.vertices.push([x-dx/2,y-dy/2,0],[x+dx/2,y-dy/2,0],[x+dx/2,y+dy/2,0],[x-dx/2,y+dy/2,0]);
    b.triangles.push([n,n+1,n+2],[n,n+2,n+3]);
  }
  // Sampled scalar field: amplitude bins are static children of shared phase
  // groups. Both signs use the same clock; zero amplitude remains black.
  const layers = [], parts = [];
  for (let p=0; p<phases; p++) for (const sign of [1,-1]) {
    const children = [];
    for (let level=0; level<levels; level++) {
      const b = buckets[p*levels+level];
      if (!b.vertices.length) continue;
      children.push(s.mesh(`field-${p}-${level}-${sign}`,{
        vertices:b.vertices,triangles:b.triangles,shading:'unlit',
        fill:sign===1 ? Color.BLUE : Color.PURPLE,stroke:Color.NONE,
        opacity:0.88*(level+0.5)/levels
      }));
    }
    const phase = 2*Math.PI*p/phases;
    const opacityAt = t => Math.max(0,sign*Math.cos(phase-omega*t));
    const mesh = s.group(`phase-${p}-${sign}`,children,{opacity:opacityAt(0)});
    layers.push({mesh,opacityAt}); parts.push(mesh);
  }
  const field = s.group('superposed-field',parts,{opacity:0});
  const sources = [];
  for (let index=0; index<2; index++) {
    const x = index===0 ? -a : a;
    s.circle(`source-${index+1}-backing`,{position:[x,0,0.1],radius:0.23,fill:Color.BLACK,stroke:Color.NONE});
    const ring = s.circle(`source-${index+1}-oscillator`,{position:[x,0,0.2],radius:0.17,fill:Color.NONE,stroke:Color.WHITE,strokeWidth:0.025});
    const point = s.circle(`source-${index+1}`,{position:[x,0,0.3],radius:0.065,fill:Color.WHITE,stroke:Color.NONE});
    const label = s.latex(`source-${index+1}-label`,{tex:`S_${index+1}`,fontSize:0.25,fill:Color.WHITE});
    s.attach(label,point,{offset:[0,-0.39,0.1]});
    sources.push(ring);
  }
  s.text('model-note',{text:'Equal-amplitude model',position:[-2.65,3.1],fontSize:0.25,fill:Color.GREY_A});
  const nodeLabel = s.text('node-label',{text:'Fixed nodes',position:[2.75,3.1],fontSize:0.28,fill:Color.YELLOW,opacity:0});
  s.latex('shared-wave-formula',{
    tex:String.raw`u=\cos(kr_1-\omega t)+\cos(kr_2-\omega t)`,
    position:[0,-3.16],fontSize:0.31,fill:Color.WHITE
  });
  const nodes = [];
  for (let m=0; (m+0.5)*wavelength<2*a; m++) {
    const h = (m+0.5)*wavelength/2, b = Math.sqrt(a*a-h*h);
    for (const sign of [-1,1]) {
      const points = [];
      for (let j=0; j<=80; j++) {
        const y = -ymax+2*ymax*j/80;
        points.push([sign*h*Math.sqrt(1+y*y/(b*b)),y,0.08]);
      }
      nodes.push(s.path(`node-${m}-${sign}`,{points,stroke:Color.YELLOW,strokeWidth:0.014,fill:Color.NONE,opacity:0}));
    }
  }
  const ly = 2.52, lh = 1.5*wavelength/2;
  const lx = lh*Math.sqrt(1+ly*ly/(a*a-lh*lh));
  const leader = s.line('node-leader',{points:[[2.75,2.9,0.1],[lx,ly,0.1]],stroke:Color.YELLOW,strokeWidth:0.014,opacity:0});
  // Reveal stationary cancellation after one cycle, continue through two more,
  // and retain the final field for a short frozen inspection.
  const motionEnd = D*0.9, steps = 36;
  for (let step=1; step<=steps; step++) {
    const t = motionEnd*step/steps;
    const actions = layers.map(({mesh,opacityAt}) => mesh.animate({opacity:opacityAt(t)}));
    for (const ring of sources) actions.push(ring.scaleTo(0.76+0.24*Math.cos(omega*t)));
    if (step===1) actions.push(field.fadeIn());
    if (step===13) {
      for (const node of nodes) actions.push(node.fadeIn());
      actions.push(nodeLabel.fadeIn(),leader.fadeIn());
    }
    play(actions,t-cursor);
  }
  s.wait(D-cursor);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-kepler\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '3d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const duration = __narration.durationSec;
  let cursor = 0;
  const play = (actions, dt) => { s.play(actions, { duration: dt, ease: 'linear' }); cursor += dt; };
  const waitTo = t => { if (t > cursor) { s.wait(t - cursor); cursor = t; } };
  play(s.camera.to2D({ height: 8 }), 0);

  // Idealized, dimensionless two-body solution. The ellipse center is the
  // origin; the gravitating body is at +ae, NOT at the ellipse center.
  const a = 4, eccentricity = 0.65;
  const b = a * Math.sqrt(1 - eccentricity * eccentricity);
  const focusPosition = [a * eccentricity, 0, 0];
  const period = duration * 0.8;
  const startTime = duration * 0.05;
  const meanStart = -Math.PI / 8;
  function eccentricAnomaly(mean) {
    let E = mean;
    for (let j = 0; j < 12; j++) {
      E -= (E - eccentricity * Math.sin(E) - mean) / (1 - eccentricity * Math.cos(E));
    }
    return E;
  }
  function point(mean, z = 0) {
    const E = eccentricAnomaly(mean);
    return [a * Math.cos(E), b * Math.sin(E), z];
  }
  const fanSegments = 64;
  function sectorGeometry(begin, end) {
    const vertices = [[focusPosition[0], 0, -0.018]];
    for (let j = 0; j <= fanSegments; j++) {
      vertices.push(point(begin + (end - begin) * j / fanSegments, -0.018));
    }
    const triangles = [];
    for (let j = 0; j < fanSegments; j++) triangles.push([0, j + 1, j + 2]);
    return { vertices, triangles, shading: 'unlit' };
  }

  s.text('model-note', { text: 'Idealized two-body orbit', position: [0, 2.82], fontSize: 0.29, fill: Color.GREY_A });
  let v, planet, star, radius, periSector, apoSector;
  s.view('orbital-model', {
    rect: [0.025, 0.12, 0.95, 0.76], orbit: false,
    camera: { yaw: -0.10, pitch: 0.88, height: 5.6, distance: 18, perspective: 0.15 }
  }, view => {
    v = view;
    const planeVertices = [[0, 0, -0.07]];
    const planeTriangles = [];
    const orbitPoints = [];
    for (let j = 0; j <= 192; j++) {
      const E = 2 * Math.PI * j / 192;
      const p = [a * Math.cos(E), b * Math.sin(E), 0];
      orbitPoints.push(p);
      planeVertices.push([p[0], p[1], -0.07]);
      if (j > 0) planeTriangles.push([0, j, j + 1]);
    }
    v.mesh('orbital-plane', { vertices: planeVertices, triangles: planeTriangles, fill: Color.GREY_E, opacity: 0.16, stroke: Color.NONE, shading: 'unlit' });
    v.path('kepler-ellipse', { points: orbitPoints, fill: Color.NONE, stroke: Color.GREY_A, strokeWidth: 0.023 });
    star = v.sphere('central-body-at-focus', {
      position: focusPosition, radius: 0.20, fill: Color.GOLD,
      texture: { pattern: 'noise', color: Color.GOLD_B, scale: 12, seed: 31, bumpStrength: 0.001 },
      material: { roughness: 0.8, specular: 0.15, emissive: Color.GOLD, emissiveIntensity: 0.18 }
    });
    planet = v.sphere('orbiting-planet', {
      position: point(meanStart), radius: 0.145, fill: Color.BLUE_B,
      texture: { pattern: 'marble', color: Color.BLUE_E, scale: [4, 9, 4], seed: 12, bumpStrength: 0.001 },
      material: { roughness: 0.65, specular: 0.25 }
    });
    radius = v.line3D('instantaneous-radius', { stroke: Color.GOLD, strokeWidth: 0.019 });
    v.connect(radius, star, planet);
    const focusLabel = v.text('focus-label', { text: 'focus', fontSize: 0.23, fill: Color.GOLD, billboard: true });
    v.attach(focusLabel, star, { offset: [0, 3.05, 0.045] });
    const peri = v.sphere('periapsis-mark', { radius: 0.027, position: [a, 0, 0], fill: Color.WHITE });
    const apo = v.sphere('apoapsis-mark', { radius: 0.027, position: [-a, 0, 0], fill: Color.WHITE });
    const periLabel = v.text('periapsis-label', { text: 'periapsis', fontSize: 0.23, billboard: true, fill: Color.GREY_A });
    const apoLabel = v.text('apoapsis-label', { text: 'apoapsis', fontSize: 0.23, billboard: true, fill: Color.GREY_A });
    v.attach(periLabel, peri, { offset: [-0.1, -2.0, 0.04] });
    v.attach(apoLabel, apo, { offset: [0.1, 2.0, 0.04] });
  });

  function boundary(id, mean, color) {
    const marker = v.sphere(id + '-point', { position: point(mean), radius: 0.034, fill: color });
    const ray = v.line3D(id + '-ray', { stroke: { color, opacity: 0.65 }, strokeWidth: 0.014 });
    v.connect(ray, star, marker);
  }
  function readout(id, subscript, x, color) {
    return s.latex(id, {
      tex: '\\Delta t_{\\mathrm{' + subscript + '}}/T = \\animnum{elapsed}',
      numbers: { elapsed: 0 }, numberFormat: { decimals: 3, digits: 1 },
      position: [x, -2.66], fontSize: 0.30, fill: color
    });
  }
  waitTo(startTime);
  const periBegin = -Math.PI / 8, periEnd = Math.PI / 8;
  const apoBegin = 7 * Math.PI / 8, apoEnd = 9 * Math.PI / 8;
  periSector = v.mesh('periapsis-swept-area', { ...sectorGeometry(periBegin, periBegin), fill: Color.BLUE, opacity: 0.43, stroke: Color.NONE });
  boundary('peri-sector-start', periBegin, Color.BLUE);
  const periTime = readout('peri-elapsed-time', 'p', 3.0, Color.BLUE_B);
  let apoTime;

  // Constant increments of mean anomaly give constant increments of physical
  // time. The 50 ms chords approximate the exact solved orbit, not constant
  // speed in eccentric anomaly or a decorative eased ellipse traversal.
  const steps = 320;
  for (let i = 0; i < steps; i++) {
    if (i === 160) {
      apoSector = v.mesh('apoapsis-swept-area', { ...sectorGeometry(apoBegin, apoBegin), fill: Color.TEAL, opacity: 0.43, stroke: Color.NONE });
      boundary('apo-sector-start', apoBegin, Color.TEAL);
      apoTime = readout('apo-elapsed-time', 'a', -3.0, Color.TEAL_A);
    }
    const nextMean = meanStart + 2 * Math.PI * (i + 1) / steps;
    const actions = [planet.moveTo(point(nextMean))];
    if (i < 40) {
      actions.push(periSector.morphTo({ kind: 'mesh', ...sectorGeometry(periBegin, nextMean) }));
      actions.push(periTime.countTo({ elapsed: (i + 1) / steps }));
    }
    if (i >= 160 && i < 200) {
      actions.push(apoSector.morphTo({ kind: 'mesh', ...sectorGeometry(apoBegin, nextMean) }));
      actions.push(apoTime.countTo({ elapsed: (i + 1 - 160) / steps }));
    }
    play(actions, period / steps);
    if (i === 39) {
      boundary('peri-sector-end', periEnd, Color.BLUE);
      v.latex('peri-area-label', { tex: 'A_{\\mathrm p}', position: [3.35, 0.65, 0.08], fontSize: 0.32, fill: Color.BLUE_A, billboard: true });
    }
    if (i === 199) {
      boundary('apo-sector-end', apoEnd, Color.TEAL);
      v.latex('apo-area-label', { tex: 'A_{\\mathrm a}', position: [-2.65, 0, 0.08], fontSize: 0.32, fill: Color.TEAL_A, billboard: true });
      s.latex('equal-areas', { tex: 'A_{\\mathrm p}=A_{\\mathrm a}', position: [0, -2.66], fontSize: 0.37, fill: Color.WHITE });
    }
  }
  play(radius.fadeOut(), duration * 0.02);
  waitTo(duration);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-lipid\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '3d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const D = __narration.durationSec;
  let cursor = 0;
  const hold = duration => { s.wait(duration); cursor += duration; };
  const play = (actions, duration, ease = 'smooth') => {
    s.play(actions, { duration, ease }); cursor += duration;
  };
  // Coordinates: X spans the membrane, Y is its normal, Z is depth.
  // This is an idealized molecular-scale construction, not atom coordinates.
  let ions = [];
  s.view('membrane-view', {
    rect: [0, 0, 1, 1], orbit: true, orbitHitTest: 'geometry',
    camera: { yaw: 0.20, pitch: 0.28, height: 10.4, distance: 24, perspective: 0 }
  }, v => {
    const membraneParts = [];
    const headY = 1.36;
    for (let ix = -5; ix <= 5; ix++) {
      for (let iz = -3; iz <= 3; iz++) {
        const x = ix * 0.65;
        const z = iz * 0.60;
        // A cylindrical protein footprint plus a front inspection cutaway.
        if (Math.hypot(x, z) < 1.48 || (z >= 0 && Math.abs(x) < 1.5)) continue;
        for (const side of [-1, 1]) {
          const id = `lipid-${ix + 5}-${iz + 3}-${side > 0 ? 'outer' : 'inner'}`;
          const parts = [];
          parts.push(v.sphere(`${id}-head`, {
            position: [x, side * headY, z], radius: 0.245,
            fill: Color.BLUE, stroke: Color.NONE,
            material: { roughness: 0.72, specular: 0.18 }
          }));
          for (let tail = 0; tail < 2; tail++) {
            const points = [];
            for (let j = 0; j <= 7; j++) {
              const f = j / 7;
              const kink = tail === 1 && j > 4 ? (j - 4) * 0.028 : 0;
              points.push([
                x + (tail === 0 ? -0.115 : 0.115) + (j % 2 ? 0.035 : -0.035) + kink,
                side * (1.23 - 1.10 * f),
                z + (tail === 0 ? -0.025 : 0.025)
              ]);
            }
            parts.push(v.tube(`${id}-tail-${tail}`, {
              points, radius: 0.064, radialSegments: 6,
              fill: Color.GREY_B, stroke: Color.NONE,
              material: { roughness: 0.9, specular: 0.1 }
            }));
          }
          membraneParts.push(v.group(id, parts));
        }
      }
    }
    v.group('bilayer', membraneParts);

    // Thick, fluted protein wall with a continuous aqueous lumen.
    // Remove only the observer-facing sector; cap its exposed section faces.
    const a0 = 1.12, a1 = 2 * Math.PI - 0.72;
    const sectors = 7;
    const proteinParts = [];
    const innerRadius = y => 0.49 + 0.20 * Math.pow(Math.abs(y) / 1.76, 3);
    const outerRadius = (a, y) => 1.08 + 0.10 * Math.cos(6 * a) + 0.09 * Math.cos(y * 1.6) + 0.035 * Math.sin(a * 3 + y);
    for (let k = 0; k < sectors; k++) {
      const start = a0 + (a1 - a0) * k / sectors;
      const finish = a0 + (a1 - a0) * (k + 1) / sectors;
      const na = 8, ny = 24;
      const vertices = [], triangles = [];
      for (let wall = 0; wall < 2; wall++) {
        for (let j = 0; j <= ny; j++) {
          const y = -1.76 + 3.52 * j / ny;
          for (let i = 0; i <= na; i++) {
            const a = start + (finish - start) * i / na;
            const r = wall === 0 ? outerRadius(a, y) : innerRadius(y);
            vertices.push([r * Math.sin(a), y, r * Math.cos(a)]);
          }
        }
      }
      const layer = (na + 1) * (ny + 1);
      const index = (wall, j, i) => wall * layer + j * (na + 1) + i;
      const quad = (a, b, c, d) => { triangles.push([a, b, c], [a, c, d]); };
      for (let j = 0; j < ny; j++) {
        for (let i = 0; i < na; i++) {
          quad(index(0,j,i), index(0,j,i+1), index(0,j+1,i+1), index(0,j+1,i));
          quad(index(1,j,i), index(1,j+1,i), index(1,j+1,i+1), index(1,j,i+1));
        }
      }
      for (let i = 0; i < na; i++) {
        quad(index(0,ny,i), index(0,ny,i+1), index(1,ny,i+1), index(1,ny,i));
        quad(index(0,0,i), index(1,0,i), index(1,0,i+1), index(0,0,i+1));
      }
      for (let j = 0; j < ny; j++) {
        quad(index(0,j,0), index(0,j+1,0), index(1,j+1,0), index(1,j,0));
        quad(index(0,j,na), index(1,j,na), index(1,j+1,na), index(0,j+1,na));
      }
      proteinParts.push(v.mesh(`channel-wall-${k}`, {
        vertices, triangles, shading: 'smooth', fill: k % 2 ? Color.GOLD_D : Color.GOLD,
        stroke: Color.NONE, material: { roughness: 0.72, specular: 0.18 }
      }));
    }
    v.group('channel-protein', proteinParts);

    // Local labels stay upright when inspecting the spatial model.
    v.text('heads-label', {
      text: 'Hydrophilic heads', position: [-4.15, 2.26, 0.95],
      fontSize: 0.29, fill: Color.BLUE_A, billboard: true
    });
    v.line3D('heads-leader', {
      points: [[-3.70, 1.97, 0.95], [-3.25, 1.55, 1.20]],
      stroke: Color.BLUE_A, strokeWidth: 0.016
    });
    v.text('tails-label', {
      text: 'Hydrophobic tails', position: [-5.08, -0.42, 1.55],
      fontSize: 0.29, fill: Color.WHITE, billboard: true
    });
    v.line3D('tails-leader', {
      points: [[-3.78, -0.42, 1.55], [-3.19, 0.50, 1.8]],
      stroke: Color.GREY_B, strokeWidth: 0.016
    });
    v.text('pore-label', {
      text: 'Channel pore', position: [2.35, 2.48, 0.2],
      fontSize: 0.32, fill: Color.GOLD_A, billboard: true
    });
    v.line3D('pore-leader', {
      points: [[1.40, 2.24, 0.2], [0.50, 1.87, 0.2]],
      stroke: Color.GOLD_A, strokeWidth: 0.016
    });
    for (let i = 0; i < 3; i++) {
      const ion = v.sphere(`ion-${i}`, {
        radius: 0.18, position: [(i - 1) * 0.8, 2.85, 0],
        fill: Color.TEAL_A, stroke: Color.NONE,
        material: { roughness: 0.48, specular: 0.22 }
      });
      const charge = v.text(`ion-charge-${i}`, {
        text: '+', fontSize: 0.25, fill: Color.WHITE, billboard: true,
        billboardOffset: [0, 0, 0.19]
      });
      v.attach(charge, ion, { offset: [0, 0, 0] });
      ions.push(ion);
    }
    v.text('ions-label', {
      text: 'Ions', position: [-0.2, 3.53, 0], fontSize: 0.30,
      fill: Color.TEAL_A, billboard: true
    });
  });
  // Screen annotation is deliberately outside the orbiting model.
  s.text('schematic-note', {
    text: 'Schematic cutaway - not to scale', space: 'screen',
    position: [0, 0], viewportOffset: [0, -0.35],
    fontSize: 19, fill: Color.GREY_A
  });

  hold(D * 0.12);
  for (let i = 0; i < ions.length; i++) {
    // Dock above the entrance; all transmembrane travel stays on the lumen axis.
    play(ions[i].moveTo([0, 2.15, 0]), D * 0.045);
    play(ions[i].moveTo([0, -2.15, 0]), D * 0.16, 'linear');
    // Spread only after completely clearing the lower membrane surface.
    play(ions[i].moveTo([(i - 1) * 0.8, -2.85, 0]), D * 0.04);
  }
  hold(D - cursor);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-planetary\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '3d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const T = __narration.durationSec;
  let cursor = 0;
  function play(actions, duration, ease = 'linear') {
    s.play(actions, { duration, ease });
    cursor += duration;
  }
  function until(time) {
    if (time > cursor) s.wait(time - cursor);
    cursor = time;
  }
  play(s.camera.to2D({ height: 10 }), 0);

  // Idealized, generated involute geometry, in XY; every shaft is parallel to Z.
  // Common module and pressure angle. Nr = Ns + 2 Np; (Nr + Ns)/3 is integral.
  const Ns = 24, Np = 18, Nr = 60, module = 0.1;
  const rs = module * Ns / 2, rp = module * Np / 2;
  const orbitRadius = rs + rp;
  const pressure = 20 * Math.PI / 180;
  const tau = 2 * Math.PI;
  const carrierTurn = tau / 3;
